describe('Save Search Query Feature', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should successfully save a search query and display confirmation', () => {
    // Perform a search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();
    cy.intercept('GET', '/api/search?q=laptop').as('searchRequest');
    cy.wait('@searchRequest');

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Click save search button
    cy.get('[data-testid="save-search-button"]').click();
    cy.intercept('POST', '/api/search/save').as('saveSearchRequest');
    cy.wait('@saveSearchRequest');

    // Verify success confirmation message
    cy.get('[data-testid="save-success-message"]')
      .should('be.visible')
      .should('contain', 'Search query saved successfully');

    // Verify save button is disabled after saving
    cy.get('[data-testid="save-search-button"]').should('be.disabled');

    // Verify saved query is listed in saved searches
    cy.get('[data-testid="saved-searches-list"]')
      .should('be.visible')
      .should('contain', 'laptop');
  });

  it('should handle saving a search query with invalid characters and display error', () => {
    // Perform a search with special characters
    cy.get('[data-testid="search-input"]').type('laptop & monitor!');
    cy.get('[data-testid="search-button"]').click();
    cy.intercept('GET', '/api/search?q=laptop%26+monitor%21').as('searchRequest');
    cy.wait('@searchRequest');

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Attempt to save the search
    cy.get('[data-testid="save-search-button"]').click();
    cy.intercept('POST', '/api/search/save', { statusCode: 441, body: { error: 'Invalid characters in search query' } }).as('saveSearchRequest');
    cy.wait('@saveSearchRequest');

    // Verify error message is displayed
    cy.get('[data-testid="save-error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid characters in search query');

    // Verify save button is re-enabled
    cy.get('[data-testid="save-search-button"]').should('not.be.disabled');

    // Verify saved searches list does not contain the invalid query
    cy.get('[data-testid="saved-searches-list"]')
      .should('not.contain', 'laptop & monitor!');
  });
});
